// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address owner = address(0xb0b);

    function setUp() public {
        vm.prank(owner);
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 depositAmount) public {
        bound(depositAmount, 0, 1 ether);
        vm.assume(depositAmount > 0);

        vm.deal(owner, depositAmount);

        vm.prank(owner);
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        uint256 ownerBalanceBefore = address(owner).balance;
        uint256 contractBalanceBefore = address(c).balance;

        vm.prank(owner);
        c.withdrawAll();

        uint256 ownerBalanceAfter = address(owner).balance;
        uint256 ownerIncrease = ownerBalanceAfter - ownerBalanceBefore;

        assertTrue(ownerIncrease == contractBalanceBefore);
    }
}
